typedef float time_value_t;

enum
{
  FEMENUCMD_END = 14,
  NUM_CONTROLLER_PORTS = 2
};

class FEMenu
{
  char data[116];

public:
  virtual ~FEMenu();
  virtual void setBack(FEMenu *, int = 1);
  virtual void setHigh(void *, bool = true);
  virtual void setVis(void *);
  virtual void Add(void *);
  virtual void Init();
  virtual void Load(bool);
  virtual void Load();
  virtual void Draw();
  virtual void DrawTop();
  virtual void UpdateInScene();
  virtual void Update(time_value_t);
  virtual void HighlightDefault();
  virtual void OnActivate();
  virtual void OnActivate(int);
  virtual void OnUnactivate(FEMenu *);
  virtual void OnSelect(int);
  virtual void OnStart(int);
  virtual void OnUp(int);
  virtual void OnDown(int);
  virtual void OnLeft(int);
  virtual void OnRight(int);
  virtual void OnCross(int);
  virtual void OnTriangle(int);
  virtual void OnSquare(int);
  virtual void OnCircle(int);
  virtual void OnL1(int);
  virtual void OnR1(int);
  virtual void OnL2(int);
  virtual void OnR2(int);
  virtual void OnAnyButtonPress(int, int);
  virtual void OnButtonRelease(int, int);
};

extern int getButtonState(int, int);

class FEMenuSystem
{
protected:
  bool button_down[FEMENUCMD_END][NUM_CONTROLLER_PORTS];
  int device_flags;

public:
  FEMenu **menus;
  void *manager;
  int active;
  int size;
  int count;
  void *font;

  virtual void InitAll();
  virtual void Add(FEMenu *);
  virtual void MakeActive(int, int = 1);
  virtual void Update(time_value_t);
  virtual void UpdateButtonDown();
  virtual void Draw();
  virtual void Select(int, int) = 0;
  virtual void Exit();
  virtual void startDraw(int = -1, const bool = true);
  virtual void endDraw(const bool = true);
  virtual FEMenu *GetActiveMenu();

protected:
  virtual void cons(int, void *, void *);
  virtual void OnButtonPress(int, int);
};

void FEMenuSystem::Update(time_value_t time_inc)
{
  int i, j;

  menus[active]->Update(time_inc);

  for (i = 0; i < FEMENUCMD_END; i++)
    for (j = 0; j < NUM_CONTROLLER_PORTS; j++)
    {
      if (button_down[i][j] && !getButtonState(i, j))
      {
        button_down[i][j] = false;
        if (device_flags & (1 << j))
          menus[active]->OnButtonRelease(j, i);
        return;
      }
      else if (!button_down[i][j] && getButtonState(i, j))
      {
        button_down[i][j] = true;
        if (device_flags & (1 << j))
          OnButtonPress(i, j);
        return;
      }
    }
}
